CREATE TABLE pwodwi (
  id INTEGER PRIMARY KEY,
  non TEXT NOT NULL,
  pri REAL,
  kantite INTEGER DEFAULT 0
);

INSERT INTO pwodwi (non, pri, kantite) VALUES
  ('Diri 25lb', 250.50, 100),
  ('Lwil 1L', 180.00, 50);

SELECT * FROM pwodwi;

SELECT non, pri FROM pwodwi
WHERE kantite > 0 AND pri BETWEEN 50 AND 300
ORDER BY pri DESC
LIMIT 5;

SELECT non FROM pwodwi WHERE non LIKE 'D%';

-- Tcheke anvan w modifye!
SELECT * FROM pwodwi WHERE id = 1;

UPDATE pwodwi
SET pri = 275, kantite = kantite - 5
WHERE id = 1;

DELETE FROM pwodwi WHERE kantite = 0;

CREATE TABLE kòmand (
  id INTEGER PRIMARY KEY,
  kliyan_id INTEGER REFERENCES kliyan(id),
  total REAL
);

SELECT k.non, c.total
FROM kliyan k
INNER JOIN kòmand c ON c.kliyan_id = k.id
WHERE c.total > 1000;

CREATE INDEX idx_kòmand_kliyan ON kòmand(kliyan_id);
CREATE INDEX idx_pwodwi_pri ON pwodwi(pri);

EXPLAIN QUERY PLAN
SELECT * FROM kòmand WHERE kliyan_id = 7;

