CREATE VIRTUAL TABLE atik_fts USING fts5(tit, kontni);

INSERT INTO atik_fts (tit, kontni) VALUES
  ('Resèt soup', 'Yon bon soup joumou ak vyann'),
  ('Gid mango', 'Tout sou mango ak bannann');

SELECT tit, bm25(atik_fts) AS skor
FROM atik_fts
WHERE atik_fts MATCH 'mango*'
ORDER BY skor;

CREATE TRIGGER odit_pri
AFTER UPDATE OF pri ON pwodwi
BEGIN
  INSERT INTO istwa_pri(pwodwi_id, ansyen_pri, nouvo_pri, dat)
  VALUES (OLD.id, OLD.pri, NEW.pri, datetime('now'));
END;

CREATE TRIGGER kenbe_fts
AFTER INSERT ON pwodwi
BEGIN
  INSERT INTO pwodwi_fts(rowid, non) VALUES (NEW.rowid, NEW.non);
END;
